// PATTERN 1: LINEAR RECURSION — one call, shrinks by 1
function sumArray(arr, i = 0) {
    if (i === arr.length) return 0;           // base case
    return arr[i] + sumArray(arr, i + 1);     // trust: sumArray(i+1) is correct
}
// Trust the recursion: assume sumArray(arr, 1) correctly sums arr[1..n-1]
// Then sumArray(arr, 0) = arr[0] + that correct sum

// PATTERN 2: BINARY RECURSION — two calls, halves the problem
function binarySum(arr, lo = 0, hi = arr.length - 1) {
    if (lo === hi) return arr[lo];            // base case: single element
    const mid = Math.floor((lo + hi) / 2);
    return binarySum(arr, lo, mid) +          // left half
           binarySum(arr, mid + 1, hi);       // right half
}
// Time: O(n) — visits each element once despite two calls
// Space: O(log n) — call stack depth is log n (halving each time)

// PATTERN 3: TAIL RECURSION — last operation is the call
function factorial_tail(n, accumulator = 1) {
    if (n <= 1) return accumulator;           // base case: return accumulated result
    return factorial_tail(n - 1, n * accumulator); // tail position: nothing after the call
}
// factorial_tail(5) -> factorial_tail(4, 5) -> factorial_tail(3, 20)
//                   -> factorial_tail(2, 60) -> factorial_tail(1, 120) -> 120
// The accumulator carries the result forward — no pending computation on return

// PATTERN 4: TREE RECURSION — multiple calls, branching tree
function countPaths(m, n) {
    // Count paths from top-left to bottom-right of m x n grid, moving only right/down
    if (m === 1 || n === 1) return 1;         // base case: only one path along an edge
    return countPaths(m - 1, n) +             // came from above
           countPaths(m, n - 1);              // came from left
}
// countPaths(3,3) = 6 paths  Time: O(2^(m+n))  Space: O(m+n) stack depth
// Memoised: O(m*n) — next lesson

