// NAIVE FIBONACCI — O(2^n): catastrophically slow
function fib_naive(n) {
    if (n <= 1) return n;
    return fib_naive(n - 1) + fib_naive(n - 2);
}
// fib_naive(40): ~1 billion calls. fib_naive(50): ~1 trillion calls.

// TOP-DOWN MEMOISATION — O(n) time, O(n) space
function fib_memo(n, cache = new Map()) {
    if (n <= 1) return n;                    // base cases
    if (cache.has(n)) return cache.get(n);  // cache hit: O(1)
    const result = fib_memo(n-1, cache) + fib_memo(n-2, cache);
    cache.set(n, result);                    // store before returning
    return result;
}
// fib_memo(40): exactly 41 unique subproblems computed
// Each fib(k) for k=0..n computed once, cached, reused

// BOTTOM-UP TABULATION — O(n) time, O(n) space, no call stack
function fib_bottom_up(n) {
    if (n <= 1) return n;
    const dp = new Array(n + 1);
    dp[0] = 0; dp[1] = 1;
    for (let i = 2; i <= n; i++) dp[i] = dp[i-1] + dp[i-2];
    return dp[n];
}

// SPACE-OPTIMISED — O(n) time, O(1) space: only keep last two values
function fib_optimal(n) {
    if (n <= 1) return n;
    let prev2 = 0, prev1 = 1;
    for (let i = 2; i <= n; i++) {
        const curr = prev1 + prev2;
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

// GENERALISED MEMOISATION TEMPLATE — apply to any pure function
function memoize(fn) {
    const cache = new Map();
    return function(...args) {
        const key = JSON.stringify(args);
        if (cache.has(key)) return cache.get(key);
        const result = fn.apply(this, args);
        cache.set(key, result);
        return result;
    };
}

