// MERGE SORT — O(n log n) time, O(n) space
function mergeSort(arr) {
    // BASE CASE: 0 or 1 elements are already sorted
    if (arr.length <= 1) return arr;

    // DIVIDE: split in half
    const mid = Math.floor(arr.length / 2);
    const left  = mergeSort(arr.slice(0, mid));  // sort left half
    const right = mergeSort(arr.slice(mid));       // sort right half

    // CONQUER: merge two sorted halves
    return merge(left, right);
}

function merge(left, right) {
    const result = [];
    let l = 0, r = 0;

    // Compare front elements, take the smaller
    while (l < left.length && r < right.length) {
        if (left[l] <= right[r]) {   // <= preserves stability
            result.push(left[l++]);
        } else {
            result.push(right[r++]);
        }
    }
    // Append remaining elements (one side will be exhausted first)
    while (l < left.length)  result.push(left[l++]);
    while (r < right.length) result.push(right[r++]);
    return result;
}

// RECURSION TREE PROOF:
// Level 0: 1 problem of size n        -> O(n) merge work
// Level 1: 2 problems of size n/2     -> O(n/2)*2 = O(n) merge work
// Level 2: 4 problems of size n/4     -> O(n/4)*4 = O(n) merge work
// ...
// Level log n: n problems of size 1   -> base cases, no merge
// Total levels: log n, each doing O(n) work -> O(n log n)

// MERGE SORT APPLICATION: Count Inversions
// An inversion is a pair (i,j) where i<j but arr[i]>arr[j]
// Merge sort can count them in O(n log n) by counting cross-merges
function countInversions(arr) {
    if (arr.length <= 1) return { sorted: arr, count: 0 };
    const mid = Math.floor(arr.length / 2);
    const { sorted: L, count: lc } = countInversions(arr.slice(0, mid));
    const { sorted: R, count: rc } = countInversions(arr.slice(mid));
    let count = lc + rc, l = 0, r = 0;
    const sorted = [];
    while (l < L.length && r < R.length) {
        if (L[l] <= R[r]) { sorted.push(L[l++]); }
        else { sorted.push(R[r++]); count += L.length - l; } // all remaining L > R[r]
    }
    while (l < L.length) sorted.push(L[l++]);
    while (r < R.length) sorted.push(R[r++]);
    return { sorted, count };
}

