// QUICKSORT with randomised pivot — O(n log n) average, O(log n) space
function quickSort(arr, lo = 0, hi = arr.length - 1) {
    if (lo >= hi) return; // base case: 0 or 1 elements

    const pivotIdx = partition(arr, lo, hi);
    quickSort(arr, lo, pivotIdx - 1); // sort left of pivot
    quickSort(arr, pivotIdx + 1, hi); // sort right of pivot
}

function partition(arr, lo, hi) {
    // RANDOMISED PIVOT: swap random element with last element
    const randIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
    [arr[randIdx], arr[hi]] = [arr[hi], arr[randIdx]];

    // LOMUTO SCHEME: pivot is arr[hi]
    const pivot = arr[hi];
    let i = lo - 1; // i tracks the boundary of the 'less than pivot' region

    for (let j = lo; j < hi; j++) {
        if (arr[j] <= pivot) {
            i++;
            [arr[i], arr[j]] = [arr[j], arr[i]]; // move to left region
        }
    }
    [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]]; // place pivot
    return i + 1; // pivot's final position
}

