// COUNTING SORT — O(n + k) where k = max value
function countingSort(arr, maxVal) {
    // Step 1: count occurrences
    const count = new Array(maxVal + 1).fill(0);
    for (const val of arr) count[val]++;

    // Step 2: produce sorted output
    const result = [];
    for (let val = 0; val <= maxVal; val++) {
        for (let c = 0; c < count[val]; c++) result.push(val);
    }
    return result;
}
// countingSort([4,2,2,8,3,3,1], 8)
// count: [0,1,2,2,1,0,0,0,1] (index=value, value=frequency)
// output: [1,2,2,3,3,4,8]  Time: O(n+k)  Space: O(k)

// STABLE COUNTING SORT — preserves original order of equal elements
function countingSortStable(arr, maxVal) {
    const count = new Array(maxVal + 1).fill(0);
    for (const val of arr) count[val]++;
    // Prefix sum: count[i] = starting output index for value i
    for (let i = 1; i <= maxVal; i++) count[i] += count[i - 1];
    // Build output right to left (preserves stability)
    const output = new Array(arr.length);
    for (let i = arr.length - 1; i >= 0; i--) {
        output[--count[arr[i]]] = arr[i];
    }
    return output;
}

// BUCKET SORT — O(n) average for uniformly distributed floats in [0,1)
function bucketSort(arr) {
    const n = arr.length;
    const buckets = Array.from({length: n}, () => []);
    // Distribute: element x goes into bucket floor(x * n)
    for (const x of arr) {
        const idx = Math.floor(x * n);
        buckets[Math.min(idx, n-1)].push(x); // clamp for x=1.0
    }
    // Sort each bucket (insertion sort is fast for small arrays)
    for (const b of buckets) b.sort((a, c) => a - c);
    // Concatenate
    return [].concat(...buckets);
}

// WHEN EACH APPLIES:
// arr = integers in [0, 100]  -> counting sort O(n)
// arr = uniformly distributed floats -> bucket sort O(n) average
// arr = large integers needing stable sort -> radix sort O(d*n)
// arr = general case -> merge sort or quicksort O(n log n)

