// VARIANT 1: EXACT MATCH — return index or -1
function binarySearch(arr, target) {
    let lo = 0, hi = arr.length - 1;
    while (lo <= hi) {
        const mid = lo + Math.floor((hi - lo) / 2); // overflow-safe
        if (arr[mid] === target) return mid;         // found
        if (arr[mid] < target)  lo = mid + 1;       // target in right half
        else                    hi = mid - 1;        // target in left half
    }
    return -1; // lo > hi: target not present
}

// VARIANT 2: LEFTMOST OCCURRENCE — first index where arr[i] === target
function lowerBound(arr, target) {
    let lo = 0, hi = arr.length - 1, result = -1;
    while (lo <= hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        if (arr[mid] === target) {
            result = mid;       // candidate: keep searching left
            hi = mid - 1;
        } else if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return result;
}

// VARIANT 3: RIGHTMOST OCCURRENCE — last index where arr[i] === target
function upperBound(arr, target) {
    let lo = 0, hi = arr.length - 1, result = -1;
    while (lo <= hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        if (arr[mid] === target) {
            result = mid;       // candidate: keep searching right
            lo = mid + 1;
        } else if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return result;
}

// VARIANT 4: INSERTION POSITION — first index where arr[i] >= target
function searchInsertPosition(arr, target) {
    let lo = 0, hi = arr.length; // hi = arr.length: target may insert at end
    while (lo < hi) {            // lo < hi not lo <= hi: hi is exclusive
        const mid = lo + Math.floor((hi - lo) / 2);
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;           // arr[mid] >= target: could be answer, keep left
    }
    return lo; // lo === hi: the insertion position
}
// [1,3,5,6], target=5 -> 2. target=2 -> 1. target=7 -> 4.

