// SEARCH IN ROTATED SORTED ARRAY — O(log n) no duplicates
function searchRotated(nums, target) {
    let lo = 0, hi = nums.length - 1;

    while (lo <= hi) {
        const mid = lo + Math.floor((hi - lo) / 2);

        if (nums[mid] === target) return mid; // found

        // Determine which half is sorted
        if (nums[lo] <= nums[mid]) {
            // LEFT HALF [lo..mid] is fully sorted
            if (nums[lo] <= target && target < nums[mid]) {
                hi = mid - 1; // target in sorted left half
            } else {
                lo = mid + 1; // target in right half
            }
        } else {
            // RIGHT HALF [mid+1..hi] is fully sorted
            if (nums[mid] < target && target <= nums[hi]) {
                lo = mid + 1; // target in sorted right half
            } else {
                hi = mid - 1; // target in left half
            }
        }
    }
    return -1;
}

// TRACE on [4,5,6,7,0,1,2], target=0:
// lo=0 hi=6 mid=3 nums[3]=7
// nums[0]=4 <= nums[3]=7: left [4,5,6,7] is sorted
// 4<=0? No -> target not in left half -> lo=4
// lo=4 hi=6 mid=5 nums[5]=1
// nums[4]=0 <= nums[5]=1: left [0,1] is sorted
// 0<=0 && 0<1? Yes -> target in left half -> hi=4
// lo=4 hi=4 mid=4 nums[4]=0 === target -> return 4

// WITH DUPLICATES — O(n) worst case
function searchRotatedWithDuplicates(nums, target) {
    let lo = 0, hi = nums.length - 1;
    while (lo <= hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        if (nums[mid] === target) return true;
        // Cannot determine sorted half when equal: shrink
        if (nums[lo] === nums[mid] && nums[mid] === nums[hi]) {
            lo++; hi--; // O(1) progress, O(n) worst case total
        } else if (nums[lo] <= nums[mid]) {
            if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;
            else lo = mid + 1;
        } else {
            if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return false;
}

