// FIND MINIMUM IN ROTATED SORTED ARRAY — O(log n)
function findMin(nums) {
    let lo = 0, hi = nums.length - 1;

    while (lo < hi) {                           // stop when single element
        const mid = lo + Math.floor((hi - lo) / 2);

        if (nums[mid] > nums[hi]) {
            lo = mid + 1;  // min is in right half (drop happens right of mid)
        } else {
            hi = mid;      // min is in left half or at mid (keep mid as candidate)
        }
    }
    return nums[lo]; // lo === hi: the minimum
}

