// BINARY SEARCH ON THE ANSWER — key advanced pattern
// Problem: 'Given n ropes of various lengths, find the maximum length L
// such that you can cut at least k pieces of length L from the ropes.'
function maxCutLength(ropes, k) {
    let lo = 1, hi = Math.max(...ropes);
    let result = 0;
    while (lo <= hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        // Can we get at least k pieces of length mid?
        const pieces = ropes.reduce((sum, r) => sum + Math.floor(r / mid), 0);
        if (pieces >= k) {
            result = mid;    // mid is feasible: try larger
            lo = mid + 1;
        } else {
            hi = mid - 1;    // mid too large: try smaller
        }
    }
    return result;
}
// Time: O(n log maxLen) — binary search on answer range [1..maxLen]

